from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Optional

from llm_harness_core import OperationResult
from llm_inspector.core import (
    ContextResult as InspectContextResult,
    EvidenceFlow,
    EvidenceItem,
    RunMetrics,
    Section,
    TokenAccounting,
    Trace,
    TraceEvent,
)
from llm_inspector.protocols import AugmentRequest, ContextAugmenter


def _copy_meta(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    return {}


def _event_provenance(payload: dict[str, Any]) -> dict[str, Any]:
    value = payload.get("provenance")
    return dict(value) if isinstance(value, dict) else {}


def _event_transformations(payload: dict[str, Any]) -> tuple[str, ...]:
    value = payload.get("transformations")
    if isinstance(value, (list, tuple)):
        return tuple(str(item) for item in value)
    return ()


def _interop_events_to_evidence_flows(events: list[Any]) -> list[EvidenceFlow]:
    flows: list[EvidenceFlow] = []
    for event in events:
        payload = dict(getattr(event, "payload", {}) or {})
        event_type = getattr(event, "event_type", None)
        if event_type == "memory_evidence_included":
            metadata = (
                dict(payload.get("metadata") or {})
                if isinstance(payload.get("metadata"), dict)
                else {}
            )
            before_text = (
                metadata.get("raw_text")
                or metadata.get("source_text")
                or metadata.get("original_text")
                or payload.get("text")
                or ""
            )
            after_text = payload.get("text") or before_text
            flows.append(
                EvidenceFlow(
                    source=str(payload.get("source") or "memory"),
                    before_text=str(before_text),
                    after_text=str(after_text),
                    stage="prompt_included",
                    score=payload.get("score"),
                    provenance=_event_provenance(payload),
                    transformations=_event_transformations(payload),
                    meta={"event_type": event_type, **metadata},
                )
            )
        elif event_type == "memory_evidence_excluded":
            metadata = (
                dict(payload.get("metadata") or {})
                if isinstance(payload.get("metadata"), dict)
                else {}
            )
            before_text = payload.get("text") or metadata.get("raw_text") or ""
            flows.append(
                EvidenceFlow(
                    source=str(payload.get("source") or "memory"),
                    before_text=str(before_text),
                    after_text="",
                    stage="excluded",
                    score=payload.get("score"),
                    provenance=_event_provenance(payload),
                    transformations=_event_transformations(payload),
                    excluded=True,
                    exclusion_reason=str(
                        payload.get("reason") or payload.get("exclusion_reason") or "excluded"
                    ),
                    meta={"event_type": event_type, **metadata},
                )
            )
    return flows


def _trace_to_inspector_trace(
    req: AugmentRequest,
    prompt_trace: Any,
    *,
    prompt_tokens: int | None = None,
    interop_events: list[Any] | None = None,
) -> Trace:
    sections = [
        Section(
            title=s.title,
            text=s.text,
            origin=s.origin,
            tokens=s.tokens,
            meta=_copy_meta(getattr(s, "meta", {})),
        )
        for s in getattr(prompt_trace, "sections", []) or []
    ]

    evidence = [
        EvidenceItem(
            text=e.text,
            source=e.source,
            score=e.score,
            meta=_copy_meta(getattr(e, "meta", {})),
        )
        for e in getattr(prompt_trace, "evidence", []) or []
    ]

    trace_token_acc = getattr(prompt_trace, "token_accounting", None)
    raw_events = list(interop_events or [])
    if not raw_events:
        raw_events = getattr(prompt_trace, "to_interop_events", lambda: [])()
    token_acc = TokenAccounting(
        target_tokens=getattr(trace_token_acc, "target_tokens", None),
        total_tokens=getattr(trace_token_acc, "total_tokens", None),
        per_origin_budget=dict(getattr(trace_token_acc, "per_origin_budget", {}) or {}),
        per_origin_used=dict(getattr(trace_token_acc, "per_origin_used", {}) or {}),
        truncated=bool(getattr(trace_token_acc, "truncated", False)),
        compressed=bool(getattr(trace_token_acc, "compressed", False)),
        notes=list(getattr(trace_token_acc, "notes", []) or []),
    )

    flags = dict(getattr(prompt_trace, "flags", {}) or {})
    evidence_flows = _interop_events_to_evidence_flows(raw_events)
    context = InspectContextResult(
        sections=sections,
        evidence=evidence,
        evidence_flows=evidence_flows,
        token_accounting=token_acc,
        signals=flags,
    )

    if not isinstance(prompt_tokens, int):
        prompt_tokens = token_acc.total_tokens
    metrics = RunMetrics(
        engine="engram",
        model=None,
        latency_ms=None,
        prompt_tokens=prompt_tokens if isinstance(prompt_tokens, int) else None,
        output_tokens=None,
        error=None,
    )

    events = list(raw_events)
    if not events:
        events = [
            TraceEvent(
                event_type="prompt_build_completed",
                source_package="engram",
                source_component="EngramAugmenter",
                payload={
                    "compressed": bool(flags.get("compressed", False)),
                    "truncated": bool(flags.get("truncated", False)),
                    "query": flags.get("query"),
                },
                message="Built prompt via Engram trace API",
                tags=("prompt", "memory"),
            )
        ]

    return Trace(
        turn=req.turn,
        context=context,
        metrics=metrics,
        events=events,
    )


@dataclass
class EngramAugmenter(ContextAugmenter):
    """Thin adapter that maps Engram prompt-building output into llm_inspector.Trace."""

    base_dir: Path
    profile: str = "default_local"
    project_id: str = "default"
    project_type: str = "programming_assistant"
    max_prompt_tokens: Optional[int] = None
    reserve_output_tokens: int = 512

    _name: str = "engram"

    @property
    def name(self) -> str:
        return self._name

    def _make_project_memory(self, req: AugmentRequest):
        from engram.project_memory import ProjectMemory

        try:
            from engram import ProjectType  # type: ignore
        except Exception:
            from engram.project_memory import ProjectType  # type: ignore

        pm = ProjectMemory(
            project_id=self.project_id,
            project_type=ProjectType(self.project_type),
            base_dir=Path(self.base_dir),
            session_id=req.session_id,
            llm_engine=None,
        )
        pm.new_session(req.session_id)
        pm.add_turn("user", req.turn.text)
        return pm

    def _augment_via_interop(self, pm: Any, req: AugmentRequest) -> Trace | None:
        build_prompt_interop = getattr(pm, "build_prompt_interop", None)
        if not callable(build_prompt_interop):
            return None

        result = build_prompt_interop(
            user_message=req.turn.text,
            query=req.query or req.turn.text,
            max_prompt_tokens=self.max_prompt_tokens,
            reserve_output_tokens=self.reserve_output_tokens,
        )
        if not isinstance(result, OperationResult) or not result.ok:
            return None
        prompt_trace = result.diagnostics.get("trace")
        if prompt_trace is None:
            return None
        return _trace_to_inspector_trace(
            req,
            prompt_trace,
            prompt_tokens=result.diagnostics.get("prompt_tokens"),
            interop_events=result.diagnostics.get("trace_events"),
        )

    def _augment_via_legacy_trace(self, pm: Any, req: AugmentRequest) -> Trace:
        result = pm.build_prompt(
            user_message=req.turn.text,
            query=req.query or req.turn.text,
            max_prompt_tokens=self.max_prompt_tokens,
            reserve_output_tokens=self.reserve_output_tokens,
            return_trace=True,
        )

        prompt_trace = result.get("trace")
        if prompt_trace is None:
            raise RuntimeError(
                "Engram did not return a prompt trace. "
                "This adapter expects either build_prompt_interop(...) diagnostics['trace'] or "
                "build_prompt(..., return_trace=True) to provide a PromptBuildTrace-compatible object."
            )
        return _trace_to_inspector_trace(
            req, prompt_trace, prompt_tokens=result.get("prompt_tokens")
        )

    def augment(self, req: AugmentRequest) -> Trace:
        pm = self._make_project_memory(req)
        try:
            interop_trace = self._augment_via_interop(pm, req)
            if interop_trace is not None:
                return interop_trace
            return self._augment_via_legacy_trace(pm, req)
        finally:
            close = getattr(pm, "close", None)
            if callable(close):
                close()


def make_engram(**kwargs) -> EngramAugmenter:
    try:
        import engram  # noqa: F401
    except Exception as e:
        raise RuntimeError(
            "Engram adapter requires Engram installed. Install with: pip install 'llm_inspector[engram]'"
        ) from e

    if "base_dir" in kwargs:
        kwargs["base_dir"] = Path(kwargs["base_dir"])
    return EngramAugmenter(**kwargs)

from __future__ import annotations

from llm_harness_core import (
    CapabilityDescriptor,
    CapabilityKind,
    MemoryRecord,
    OperationResult,
    TraceEvent,
)

from .inspectors import ComparisonReport


def describe_inspector(component: object | None = None) -> CapabilityDescriptor:
    component_name = component.__class__.__name__ if component is not None else "ContextInspector"
    return CapabilityDescriptor(
        kind=CapabilityKind.INSPECTOR,
        provider="llm_inspector",
        component=component_name,
        version="0.1.0",
        summary="Observability and comparison workflows for augmentation traces.",
        features=(
            "compare",
            "diff",
            "bundle",
            "trace_export",
            "console_rendering",
            "run_artifact_inspection",
            "run_artifact_comparison",
        ),
        input_types=("trace", "comparison_report", "run_artifact"),
        output_types=("operation_result", "trace_event[]", "json_report"),
        metadata={},
    )


def trace_to_operation_result(trace) -> OperationResult[dict]:
    return trace.to_interop_result()


def trace_to_interop_events(trace) -> list[TraceEvent]:
    return trace.to_interop_events()


def trace_to_memory_records(trace) -> list[MemoryRecord]:
    return [item.to_memory_record() for item in trace.context.evidence]


def report_to_operation_result(report: ComparisonReport) -> OperationResult[dict]:
    value = {
        "query": report.query,
        "traces": [
            {
                "name": named.name,
                "trace": named.trace.to_interop_result().value,
            }
            for named in report.traces
        ],
    }
    diagnostics = {
        "trace_count": len(report.traces),
        "adapters": [named.name for named in report.traces],
    }
    return OperationResult.success(value, diagnostics=diagnostics)

"""Robust structured-output parsing helpers for LLM responses.

This module is adapted from mature Engram utility code, but kept as a
standalone helper for the ``llm_engines`` package. It does not change the
engine contracts; it simply makes it easier for callers to recover typed data
from model text output.
"""

from __future__ import annotations

from dataclasses import dataclass
import json
import re
from typing import Any, TypeVar

from pydantic import BaseModel, ValidationError

T = TypeVar("T", bound=BaseModel)

_json_repair: Any = None
try:  # optional dependency
    import json_repair

    _json_repair = json_repair

    _HAS_JSON_REPAIR = True
except ImportError:  # pragma: no cover - exercised via behavior tests
    _HAS_JSON_REPAIR = False


@dataclass(frozen=True)
class ParseResult:
    """Result of a structured-output parsing attempt."""

    success: bool
    data: BaseModel | None
    raw_output: str
    extracted_json: str | None
    error: str | None
    repair_attempted: bool


class StructuredOutputError(Exception):
    """Raised when structured output parsing fails.

    Includes the raw output, extracted JSON (if any), and the expected schema
    in the rendered exception text to simplify debugging.
    """

    def __init__(
        self,
        message: str,
        raw_output: str,
        extracted_json: str | None,
        model_class: type[BaseModel],
    ) -> None:
        self.message = message
        self.raw_output = raw_output
        self.extracted_json = extracted_json
        self.model_class = model_class

        details = [
            f"Structured Output Parsing Failed: {message}",
            "",
            f"Expected Model: {model_class.__name__}",
            "",
        ]

        if len(raw_output) > 500:
            details.extend(
                [
                    "Raw Output (first 500 chars):",
                    raw_output[:500] + "...",
                    "",
                ]
            )
        else:
            details.extend(["Raw Output:", raw_output, ""])

        if extracted_json:
            if len(extracted_json) > 500:
                details.extend(
                    [
                        "Extracted JSON (first 500 chars):",
                        extracted_json[:500] + "...",
                        "",
                    ]
                )
            else:
                details.extend(["Extracted JSON:", extracted_json, ""])

        details.extend(
            [
                "Expected Schema:",
                json.dumps(model_class.model_json_schema(), indent=2),
            ]
        )
        super().__init__("\n".join(details))


def _strip_think_blocks(raw_output: str) -> str:
    stripped = re.sub(r"<think>.*?</think>\s*", "", raw_output, flags=re.DOTALL | re.IGNORECASE)
    open_match = re.search(r"<think>", stripped, flags=re.IGNORECASE)
    if open_match and not re.search(r"</think>", stripped, flags=re.IGNORECASE):
        stripped = stripped[: open_match.start()]
    return stripped


class StructuredOutputHandler:
    """Parse JSON-like model output into typed Pydantic objects."""

    @staticmethod
    def parse(
        raw_output: str,
        model_class: type[T],
        strict: bool = False,
        allow_repair: bool = True,
    ) -> T:
        """Parse LLM output into a Pydantic model or raise with context."""
        result = StructuredOutputHandler.parse_with_details(
            raw_output=raw_output,
            model_class=model_class,
            strict=strict,
            allow_repair=allow_repair,
        )
        if not result.success:
            raise StructuredOutputError(
                message=result.error or "Unknown structured-output parse error",
                raw_output=raw_output,
                extracted_json=result.extracted_json,
                model_class=model_class,
            )
        data = result.data
        assert data is not None
        return data  # type: ignore[return-value]

    @staticmethod
    def parse_with_details(
        raw_output: str,
        model_class: type[T],
        strict: bool = False,
        allow_repair: bool = True,
    ) -> ParseResult:
        """Parse with full success/failure metadata instead of raising."""
        extracted = StructuredOutputHandler._extract_json(raw_output)
        if not extracted:
            return ParseResult(
                success=False,
                data=None,
                raw_output=raw_output,
                extracted_json=None,
                error="No JSON found in response",
                repair_attempted=False,
            )

        try:
            data = model_class.model_validate_json(extracted)
            return ParseResult(
                success=True,
                data=data,
                raw_output=raw_output,
                extracted_json=extracted,
                error=None,
                repair_attempted=False,
            )
        except (json.JSONDecodeError, ValidationError) as exc:
            if strict:
                return ParseResult(
                    success=False,
                    data=None,
                    raw_output=raw_output,
                    extracted_json=extracted,
                    error=f"Strict mode: {exc}",
                    repair_attempted=False,
                )
            if allow_repair:
                try:
                    if not _HAS_JSON_REPAIR or _json_repair is None:
                        raise ImportError("json_repair not installed")
                    repaired = _json_repair.loads(extracted)
                    data = model_class.model_validate(repaired)
                    return ParseResult(
                        success=True,
                        data=data,
                        raw_output=raw_output,
                        extracted_json=extracted,
                        error=None,
                        repair_attempted=True,
                    )
                except Exception as repair_error:
                    return ParseResult(
                        success=False,
                        data=None,
                        raw_output=raw_output,
                        extracted_json=extracted,
                        error=f"Parse failed: {exc}\nRepair failed: {repair_error}",
                        repair_attempted=True,
                    )
            return ParseResult(
                success=False,
                data=None,
                raw_output=raw_output,
                extracted_json=extracted,
                error=str(exc),
                repair_attempted=False,
            )

    @staticmethod
    def _extract_json(raw_output: str) -> str | None:
        """Extract the first JSON object/array from common LLM output formats."""
        if not raw_output or not raw_output.strip():
            return None

        raw_output = _strip_think_blocks(raw_output)

        json_block = re.search(
            r"```(?:json)?\s*\n?(.*?)\n?```", raw_output, re.DOTALL | re.IGNORECASE
        )
        if json_block:
            return json_block.group(1).strip()

        text = raw_output.strip()
        decoder = json.JSONDecoder()
        for i, char in enumerate(text):
            if char in "[{":
                try:
                    _obj, end_idx = decoder.raw_decode(text, i)
                    return text[i:end_idx]
                except json.JSONDecodeError:
                    continue

        try:
            json.loads(text)
            return text
        except (json.JSONDecodeError, ValueError):
            return None

    @staticmethod
    def create_schema_prompt(model_class: type[BaseModel], include_examples: bool = True) -> str:
        """Generate prompt instructions that ask a model for JSON matching a schema."""
        schema = model_class.model_json_schema()
        prompt_parts = [
            "Please format your response as valid JSON matching this schema:",
            "",
            "```json",
            json.dumps(schema, indent=2),
            "```",
            "",
            "IMPORTANT:",
            "- Return ONLY the JSON object, no other text",
            "- Use double quotes for strings",
            "- Do not include comments in the JSON",
            "- Ensure all required fields are present",
            "- Follow the exact field names shown in the schema",
        ]
        if include_examples and "properties" in schema:
            example = StructuredOutputHandler._generate_example(model_class)
            if example:
                prompt_parts.extend(
                    [
                        "",
                        "Example format:",
                        "```json",
                        json.dumps(example, indent=2),
                        "```",
                    ]
                )
        return "\n".join(prompt_parts)

    @staticmethod
    def _generate_example(model_class: type[BaseModel]) -> dict[str, object] | None:
        """Generate a simple example object from a model schema."""
        try:
            schema = model_class.model_json_schema()
            example: dict[str, object] = {}
            for field_name, field_info in schema.get("properties", {}).items():
                field_type = field_info.get("type", "string")
                if field_type == "string":
                    example[field_name] = f"example_{field_name}"
                elif field_type == "integer":
                    example[field_name] = 42
                elif field_type == "number":
                    example[field_name] = 3.14
                elif field_type == "boolean":
                    example[field_name] = True
                elif field_type == "array":
                    example[field_name] = ["item1", "item2"]
                elif field_type == "object":
                    example[field_name] = {"key": "value"}
            return example
        except Exception:
            return None

    @staticmethod
    def parse_multiple(
        raw_output: str,
        model_class: type[T],
        allow_repair: bool = True,
    ) -> list[T]:
        """Parse an array of objects, or a single object, into model instances."""
        extracted = StructuredOutputHandler._extract_json(raw_output)
        if not extracted:
            return []
        try:
            data = json.loads(extracted)
            if isinstance(data, list):
                results: list[T] = []
                for item in data:
                    try:
                        results.append(model_class.model_validate(item))
                    except ValidationError:
                        if allow_repair:
                            if not _HAS_JSON_REPAIR or _json_repair is None:
                                raise ImportError("json_repair not installed")
                            repaired = _json_repair.loads(json.dumps(item))
                            results.append(model_class.model_validate(repaired))
                        else:
                            raise
                return results
            return [model_class.model_validate(data)]
        except Exception as exc:
            raise StructuredOutputError(
                message=f"Failed to parse multiple objects: {exc}",
                raw_output=raw_output,
                extracted_json=extracted,
                model_class=model_class,
            )

