from __future__ import annotations
import time
from typing import Any, Dict, List, Optional


def reciprocal_rank_fusion(
    ranked_lists: List[List[Dict[str, Any]]],
    k: int = 60,
    id_key: str = "id",
) -> List[Dict[str, Any]]:
    """Combine ranked lists using Reciprocal Rank Fusion (RRF).

    score = sum(1 / (k + rank)) across all lists.
    k=60 from original paper; configurable.
    """
    scores: dict[str, float] = {}
    items: dict[str, dict] = {}

    for ranked_list in ranked_lists:
        for rank, item in enumerate(ranked_list, start=1):
            item_id = item.get(id_key)
            if item_id is None:
                continue
            scores[item_id] = scores.get(item_id, 0.0) + 1.0 / (k + rank)
            if item_id not in items:
                items[item_id] = item

    return [
        {**items[iid], "rrf_score": score}
        for iid, score in sorted(scores.items(), key=lambda x: x[1], reverse=True)
    ]


def hybrid_episode_search(
    query: str,
    query_embedding: Optional[List[float]],
    *,
    vector_results: Optional[List[Dict[str, Any]]] = None,
    text_results: Optional[List[Dict[str, Any]]] = None,
    recency_boost: bool = True,
    importance_boost: bool = True,
    k: int = 60,
) -> List[Dict[str, Any]]:
    """Combine vector and text search via RRF with optional boosts."""
    ranked_lists = []
    if vector_results:
        ranked_lists.append(vector_results)
    if text_results:
        ranked_lists.append(text_results)
    if not ranked_lists:
        return []

    fused = reciprocal_rank_fusion(ranked_lists, k=k, id_key="id")

    now = time.time()
    for item in fused:
        score = item["rrf_score"]

        if recency_boost and "created_at" in item:
            age_days = (now - float(item["created_at"])) / 86400.0
            score *= max(0.5, 1.0 - (age_days / 30.0))

        if importance_boost and "importance" in item:
            importance = float(item.get("importance", 0.5))
            score *= 0.8 + importance * 0.4  # range [0.8, 1.2]

        item["final_score"] = score

    fused.sort(key=lambda x: x["final_score"], reverse=True)
    return fused

def _reciprocal_rank_fusion(
    self,
    dense: list[StoredChunk],
    bm25: list[tuple[str, float]],
) -> list[StoredChunk]:
    """Combine dense and BM25 rankings via Reciprocal Rank Fusion.

    RRF score = sum(1 / (k + rank_i)) across all result lists.
    k=60 is the standard constant.
    """
    rrf_scores: dict[str, float] = {}

    # Dense ranking
    for rank, chunk in enumerate(dense, start=1):
        rrf_scores[chunk.chunk_id] = rrf_scores.get(chunk.chunk_id, 0.0)
        rrf_scores[chunk.chunk_id] += (1.0 - self._bm25_weight) / (_RRF_K + rank)

    # BM25 ranking
    for rank, (cid, _score) in enumerate(bm25, start=1):
        rrf_scores[cid] = rrf_scores.get(cid, 0.0)
        rrf_scores[cid] += self._bm25_weight / (_RRF_K + rank)

    # Build a lookup from chunk_id → StoredChunk for dense results
    dense_map = {c.chunk_id: c for c in dense}

    # Sort by RRF score and return StoredChunks (dense results only for now;
    # BM25-only results would need a separate fetch — acceptable for Phase 1)
    sorted_ids = sorted(rrf_scores, key=lambda cid: rrf_scores[cid], reverse=True)
    result: list[StoredChunk] = []
    for cid in sorted_ids:
        if cid in dense_map:
            chunk = dense_map[cid]
            # Update score to reflect RRF fusion score
            object.__setattr__(chunk, "score", round(rrf_scores[cid], 6)) if hasattr(
                chunk, "__dataclass_fields__"
            ) else None
            result.append(chunk)
    return result
